fn solve(n: i8) -> bool {
    // Take absolute value to handle negative inputs
    let n = n.abs() as i32;
    
    // Extract digits
    let thousands = n / 1000;
    let hundreds = (n / 100) % 10;
    let tens = (n / 10) % 10;
    let ones = n % 10;
    
    // Check if we have at least 3 digits for the conditions
    // For numbers < 1000, thousands digit will be 0
    
    // Check first three digits (thousands, hundreds, tens)
    let first_three_equal = thousands == hundreds && hundreds == tens;
    
    // Check last three digits (hundreds, tens, ones)
    let last_three_equal = hundreds == tens && tens == ones;
    
    first_three_equal || last_three_equal
}